#!/usr/bin/env bash
# step104 — Batch 3: multi-language bot messages engine. Adds lib/watpl.js
# (composes each message in all enabled languages), wires wanotify + whatsapp
# to it, adds wa_templates.langs, seeds English/Urdu/Arabic/Roman-Urdu, and
# enables all four. Admin editor comes next (step105). Idempotent; rolls back.
set -euo pipefail
APP=/opt/gsz
TS=$(date +%Y%m%d-%H%M%S)
BAK=$APP/.bak-step104-$TS
mkdir -p "$BAK/lib" "$BAK/routes"
cp "$APP/lib/wanotify.js" "$BAK/lib/wanotify.js"
cp "$APP/routes/whatsapp.js" "$BAK/routes/whatsapp.js"
restore(){ echo "!! rollback"; cp "$BAK/lib/wanotify.js" "$APP/lib/wanotify.js"; cp "$BAK/routes/whatsapp.js" "$APP/routes/whatsapp.js"; rm -f "$APP/lib/watpl.js"; pm2 restart gsz --update-env >/dev/null 2>&1 || true; }
trap 'restore' ERR
cd "$APP"

echo "==> write lib/watpl.js + overwrite wanotify.js + whatsapp.js"
base64 -d > "$APP/lib/watpl.js" <<'B64'

B64
base64 -d > "$APP/lib/wanotify.js" <<'B64'

B64
base64 -d > "$APP/routes/whatsapp.js" <<'B64'

B64

echo "==> migrate: wa_templates.langs + seed translations + enable languages"
node <<'NODE'
require('dotenv').config();
const { Pool } = require('pg');
const p = new Pool({ host:process.env.DB_HOST, port:process.env.DB_PORT, database:process.env.DB_NAME, user:process.env.DB_USER, password:process.env.DB_PASS });
const T = {
 'whatsapp.verification_success': {
  en:"✅ Your WhatsApp is verified for {{site_name}}. You'll get your order updates and trial details right here.",
  ur:"✅ آپ کا واٹس ایپ {{site_name}} کے لیے تصدیق شدہ ہے۔ آرڈر اپڈیٹس اور ٹرائل کی تفصیلات آپ کو یہیں ملیں گی۔",
  ar:"✅ تم توثيق الواتساب الخاص بك لدى {{site_name}}. ستصلك تحديثات الطلب وتفاصيل التجربة هنا.",
  ro:"✅ Aap ka WhatsApp {{site_name}} ke liye verify ho gaya. Order updates aur trial details aap ko yahin milenge."
 },
 'whatsapp.order_received': {
  en:"🧾 {{site_name}}: we received your order {{order_number}}. We'll keep you updated here.",
  ur:"🧾 {{site_name}}: ہمیں آپ کا آرڈر {{order_number}} موصول ہوگیا۔ پیش رفت یہیں بتائیں گے۔",
  ar:"🧾 {{site_name}}: استلمنا طلبك {{order_number}}. سنوافيك بالتحديثات هنا.",
  ro:"🧾 {{site_name}}: aap ka order {{order_number}} mil gaya. Update yahin denge."
 },
 'whatsapp.payment_confirmed': {
  en:"💰 Payment confirmed for order {{order_number}}. We're processing it now.",
  ur:"💰 آرڈر {{order_number}} کی ادائیگی تصدیق ہوگئی۔ ہم ابھی پراسیس کر رہے ہیں۔",
  ar:"💰 تم تأكيد الدفع للطلب {{order_number}}. نقوم بمعالجته الآن.",
  ro:"💰 Order {{order_number}} ki payment confirm ho gayi. Hum ise process kar rahe hain."
 },
 'whatsapp.order_completed': {
  en:"🎉 Order {{order_number}} is complete. {{product_name}} is ready.",
  ur:"🎉 آرڈر {{order_number}} مکمل ہوگیا۔ {{product_name}} تیار ہے۔",
  ar:"🎉 اكتمل الطلب {{order_number}}. {{product_name}} جاهز.",
  ro:"🎉 Order {{order_number}} complete ho gaya. {{product_name}} ready hai."
 },
 'whatsapp.credentials': {
  en:"🔐 Your {{product_name}} is ready. View your details securely: {{secure_link}}",
  ur:"🔐 آپ کا {{product_name}} تیار ہے۔ اپنی تفصیلات محفوظ طریقے سے دیکھیں: {{secure_link}}",
  ar:"🔐 {{product_name}} جاهز. اعرض تفاصيلك بأمان: {{secure_link}}",
  ro:"🔐 Aap ka {{product_name}} ready hai. Apni details securely dekhein: {{secure_link}}"
 },
 'whatsapp.trial_ready': {
  en:"🎁 Your {{server_name}} free trial is ready ({{duration_label}}). View it here: {{secure_link}}",
  ur:"🎁 آپ کا {{server_name}} مفت ٹرائل تیار ہے ({{duration_label}})۔ یہاں دیکھیں: {{secure_link}}",
  ar:"🎁 تجربتك المجانية لـ {{server_name}} جاهزة ({{duration_label}}). شاهدها هنا: {{secure_link}}",
  ro:"🎁 Aap ka {{server_name}} free trial ready hai ({{duration_label}}). Yahan dekhein: {{secure_link}}"
 },
 'whatsapp.password_reset': {
  en:"🔐 Your {{site_name}} password reset code is {{code}}. It expires in 30 minutes. If this wasn't you, ignore this message.",
  ur:"🔐 {{site_name}} کے لیے آپ کا پاس ورڈ ری سیٹ کوڈ {{code}} ہے۔ یہ 30 منٹ میں ختم ہوجائے گا۔",
  ar:"🔐 رمز إعادة تعيين كلمة المرور لـ {{site_name}} هو {{code}}. ينتهي خلال 30 دقيقة.",
  ro:"🔐 {{site_name}} ka password reset code {{code}} hai. 30 minute mein expire ho jayega. Agar yeh aap ne nahi kiya to ignore karein."
 },
 'whatsapp.subscription_expiry': {
  en:"⏰ Your {{product_name}} expires on {{expiry_date}}. Message our sales number to renew.",
  ur:"⏰ آپ کا {{product_name}} {{expiry_date}} کو ختم ہورہا ہے۔ تجدید کے لیے ہمارے سیلز نمبر پر پیغام دیں۔",
  ar:"⏰ ينتهي {{product_name}} في {{expiry_date}}. راسلنا على رقم المبيعات للتجديد.",
  ro:"⏰ Aap ka {{product_name}} {{expiry_date}} ko expire ho raha hai. Renew ke liye sales number par message karein."
 },
 'whatsapp.redirect_support': {
  en:"This number is for website verification & account security only.\n\nSales: https://wa.me/{{sales_number}}\nSupport: https://wa.me/{{support_number}}",
  ur:"یہ نمبر صرف ویب سائٹ کی تصدیق اور اکاؤنٹ سیکیورٹی کے لیے ہے۔\n\nسیلز: https://wa.me/{{sales_number}}\nسپورٹ: https://wa.me/{{support_number}}",
  ar:"هذا الرقم مخصص لتوثيق الموقع وأمان الحساب فقط.\n\nالمبيعات: https://wa.me/{{sales_number}}\nالدعم: https://wa.me/{{support_number}}",
  ro:"Yeh number sirf website verification aur account security ke liye hai.\n\nSales: https://wa.me/{{sales_number}}\nSupport: https://wa.me/{{support_number}}"
 }
};
(async()=>{
  await p.query("ALTER TABLE wa_templates ADD COLUMN IF NOT EXISTS langs jsonb");
  await p.query("UPDATE wa_templates SET langs = jsonb_build_object('en', body) WHERE langs IS NULL AND body IS NOT NULL");
  await p.query("INSERT INTO wa_settings(key,value) VALUES('wa_langs','en,ur,ar,ro') ON CONFLICT(key) DO NOTHING");
  await p.query("INSERT INTO wa_settings(key,value) VALUES('wa_lang_names','en:English,ur:Urdu,ar:Arabic,ro:Roman Urdu') ON CONFLICT(key) DO NOTHING");
  let n=0;
  for (const [key, obj] of Object.entries(T)) {
    // ensure row exists with en body, then set langs
    await p.query("INSERT INTO wa_templates(key, body) VALUES($1,$2) ON CONFLICT(key) DO UPDATE SET body=COALESCE(wa_templates.body, EXCLUDED.body)", [key, obj.en]);
    await p.query("UPDATE wa_templates SET langs=$2, updated_at=now() WHERE key=$1", [key, JSON.stringify(obj)]);
    n++;
  }
  console.log('   seeded '+n+' templates in en/ur/ar/ro; languages enabled: en,ur,ar,ro');
  await p.end();
})().catch(e=>{ console.error('MIGRATION FAIL: '+e.message); process.exit(1); });
NODE

echo "==> node --check + restart"
node --check "$APP/lib/watpl.js"; node --check "$APP/lib/wanotify.js"; node --check "$APP/routes/whatsapp.js"
pm2 restart gsz --update-env >/dev/null; sleep 3
grep -q '</html>' <<<"$(curl -s -m 15 http://127.0.0.1:3900/ || true)" || { echo "!! home broken"; false; }
trap - ERR
echo "==> step104 OK — bot messages now multi-language (EN/UR/AR/Roman-Urdu). Backup: $BAK"
echo "   Admin editor to tweak wording + toggle languages comes next (step105)."
